def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: total seconds as a float (or None if value is None)
    """
    if value is None:
        return None
    return value.total_seconds()

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    import datetime
    if not isinstance(value, datetime.time):
        raise TypeError("Expected a datetime.time instance")
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    # If the value is a tuple or list, return it as a list
    if isinstance(value, (tuple, list)):
        return list(value)

    # If the value has x and y attributes (common for point-like objects)
    if hasattr(value, "x") and hasattr(value, "y"):
        # Include z if present, otherwise None
        return {
            "x": getattr(value, "x"),
            "y": getattr(value, "y"),
            "z": getattr(value, "z", None),
        }

    # If the value has a __dict__ attribute, use it
    if hasattr(value, "__dict__"):
        return dict(value.__dict__)

    # Fallback: try to convert to a list if iterable
    try:
        return list(value)
    except TypeError:
        pass

    # If all else fails, return the value as is
    return value

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self._data.keys())

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Ensure the class has a mapping of handlers
        if not hasattr(cls, "_protocol_handlers"):
            raise AttributeError(
                f"{cls.__name__} does not define a _protocol_handlers mapping"
            )

        handlers = cls._protocol_handlers

        # If a specific protocol version is requested
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
                )
            # Return a dict with the handler if it exists, otherwise empty dict
            return (
                {protocol_version: handlers[protocol_version]}
                if protocol_version in handlers
                else {}
            )

        # No specific version requested: return all handlers
        return dict(handlers)  # return a shallow copy to avoid accidental mutation

def unit_of_work(metadata=None, timeout=None):
    """Decorator to add metadata and timeout to Neo4j transaction functions."""
    def decorator(func):
        import functools
        @functools.wraps(func)
        def wrapper(tx, *args, **kwargs):
            # Validate timeout
            if timeout is not None:
                if not isinstance(timeout, (int, float)):
                    raise TypeError("timeout must be a number or None")
                if timeout < 0:
                    raise ValueError("timeout must not be negative")
            # Validate metadata
            if metadata is not None and not isinstance(metadata, dict):
                raise TypeError("metadata must be a dict or None")

            class TxProxy:
                def __init__(self, tx):
                    self._tx = tx

                def run(self, *q_args, **q_kwargs):
                    # Apply default metadata if not overridden
                    if metadata is not None and 'metadata' not in q_kwargs:
                        q_kwargs['metadata'] = metadata
                    # Apply default timeout if not overridden
                    if timeout is not None and 'timeout' not in q_kwargs:
                        q_kwargs['timeout'] = timeout
                    return self._tx.run(*q_args, **q_kwargs)

                def __getattr__(self, name):
                    return getattr(self._tx, name)

            return func(TxProxy(tx), *args, **kwargs)
        return wrapper
    return decorator

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(key)

def data(self, *keys):
    """Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no specific keys are requested, return all key/value pairs
    if not keys:
        return dict(zip(self._keys, self._values))

    result = {}
    for k in keys:
        # Treat integers as positional indexes
        if isinstance(k, int):
            if k < 0 or k >= len(self._values):
                raise IndexError(f"Index {k} out of bounds")
            key_name = self._keys[k]
            result[key_name] = self._values[k]
        else:
            # Treat everything else as a key name
            if k in self._keys:
                idx = self._keys.index(k)
                result[k] = self._values[idx]
            else:
                result[k] = None
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}
    msg = Message(0x0B, n, qid)
    self._output_queue.append(msg)
    return Response(msg, dehydration_hooks, hydration_hooks, **handlers)

def deprecated(message):
    def decorator(func):
        @__import__('functools').wraps(func)
        def wrapper(*args, **kwargs):
            __import__('warnings').warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    import sys
    import concurrent.futures

    def _run_command(command: list[str]) -> tuple[int, bytes]:
        if color and not sys.platform.startswith("win"):
            master, slave = os.openpty()
            try:
                p = subprocess.Popen(
                    command,
                    stdin=slave,
                    stdout=slave,
                    stderr=slave,
                    close_fds=True,
                )
                os.close(slave)
                out = b""
                while True:
                    try:
                        chunk = os.read(master, 4096)
                        if not chunk:
                            break
                        out += chunk
                    except OSError:
                        break
                return p.wait(), out
            finally:
                try:
                    os.close(master)
                except OSError:
                    pass
        else:
            result = subprocess.run(
                command,
                capture_output=True,
                check=False,
                **kwargs,
            )
            return result.returncode, result.stdout

    # Partition varargs into chunks that respect _max_length
    base_len = sum(len(part) + 1 for part in cmd)  # +1 for space
    chunks: list[list[str]] = []
    current: list[str] = []
    current_len = base_len
    for arg in varargs:
        arg_len = len(arg) + 1
        if current_len + arg_len > _max_length and current:
            chunks.append(current)
            current = [arg]
            current_len = base_len + arg_len
        else:
            current.append(arg)
            current_len += arg_len
    if current:
        chunks.append(current)

    # Execute commands with concurrency
    rc = 0
    outputs: list[bytes] = []

    if target_concurrency <= 1 or len(chunks) == 1:
        for chunk in chunks:
            code, out = _run_command(list(cmd) + chunk)
            if code != 0 and rc == 0:
                rc = code
            outputs.append(out)
    else:
        with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            futures = [
                executor.submit(_run_command, list(cmd) + chunk) for chunk in chunks
            ]
            for fut in concurrent.futures.as_completed(futures):
                code, out = fut.result()
                if code != 0 and rc == 0:
                    rc = code
                outputs.append(out)

    return rc, b"".join(outputs)

def parse_version(s: str) -> tuple[int, ...]:
    import re
    parts = re.split(r'\D+', s)
    nums = [int(p) for p in parts if p]
    return tuple(nums)

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize <= 0:
        raise ValueError("maxsize must be > 0")
    if ttl <= 0:
        raise ValueError("ttl must be > 0")

    def decorator(func):
        cache = {}
        order = []

        def make_key(args, kwargs):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    key += tuple(sorted((k, type(v)) for k, v in kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError('dictionary is empty')
    value = self[key]
    del self[key]
    return key, value

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
