def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(func, *args, **kwargs)
            sentinel = object()
            if lock is not None:
                if hasattr(lock, "__enter__"):
                    with lock:
                        try:
                            value = cache[k]
                        except Exception:
                            try:
                                value = cache.get(k, sentinel)
                            except Exception:
                                value = sentinel
                        if value is not sentinel:
                            return value
                        result = func(*args, **kwargs)
                        try:
                            cache[k] = result
                        except Exception:
                            pass
                        return result
                else:
                    lock.acquire()
                    try:
                        try:
                            value = cache[k]
                        except Exception:
                            try:
                                value = cache.get(k, sentinel)
                            except Exception:
                                value = sentinel
                        if value is not sentinel:
                            return value
                        result = func(*args, **kwargs)
                        try:
                            cache[k] = result
                        except Exception:
                            pass
                        return result
                    finally:
                        lock.release()
            else:
                try:
                    value = cache[k]
                except Exception:
                    try:
                        value = cache.get(k, sentinel)
                    except Exception:
                        value = sentinel
                if value is not sentinel:
                    return value
                result = func(*args, **kwargs)
                try:
                    cache[k] = result
                except Exception:
                    pass
                return result
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with limited stack depth and path depth.
    """
    import traceback, os, sys

    def _shorten_path(path, max_parts):
        parts = path.split(os.sep)
        if len(parts) > max_parts:
            return "..." + os.sep + os.path.join(*parts[-max_parts:])
        return path

    def _format_exception(exc, level=0):
        lines = []
        # Exception type and message
        exc_type = type(exc).__name__
        exc_msg = str(exc)
        lines.append(f"{'  ' * level}{exc_type}: {exc_msg}")

        # Stack trace
        tb = exc.__traceback__
        if tb:
            frames = traceback.extract_tb(tb)
            # Limit to max_level frames
            frames = frames[:max_level]
            for frame in frames:
                filename = _shorten_path(frame.filename, max_path_level)
                lines.append(f"{'  ' * level}  File \"{filename}\", line {frame.lineno}, in {frame.name}")
                if frame.line:
                    lines.append(f"{'  ' * level}    {frame.line.strip()}")
        # Handle chained exceptions
        cause = getattr(exc, "__cause__", None)
        context = getattr(exc, "__context__", None)
        if cause and not getattr(exc, "__suppress_context__", False):
            lines.append(f"{'  ' * level}Caused by:")
            lines.extend(_format_exception(cause, level + 1))
        elif context and not getattr(exc, "__suppress_context__", False):
            lines.append(f"{'  ' * level}During handling of the above exception, another exception occurred:")
            lines.extend(_format_exception(context, level + 1))
        return lines

    return "\n".join(_format_exception(e))

def is_file_exist(file_name):
        """
        Check if file name exist.
        :param file_name: File name.
        :type file_name: str
        :return: Return true (exist), false (do not exist, or invalid file name)
        :rtype bool
        """
        if not isinstance(file_name, str) or not file_name:
            return False
        try:
            return os.path.isfile(file_name)
        except Exception:
            return False

def _getTargetClass(self):
    name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = []
    # Determine the set of attribute names to inspect
    if all:
        names = dir(self)
    else:
        names = list(self.__class__.__dict__.keys())
    for name in names:
        # Skip private and special attributes
        if name.startswith('_'):
            continue
        # Skip methods and other callables
        if callable(getattr(self, name, None)):
            continue
        desc = ''
        # Try to get description from a property (if defined in class dict)
        class_attr = self.__class__.__dict__.get(name)
        if isinstance(class_attr, property):
            desc = class_attr.__doc__ or ''
        else:
            # Try to get description from the attribute's __doc__ (if any)
            attr = getattr(self, name, None)
            if hasattr(attr, '__doc__') and attr.__doc__:
                desc = attr.__doc__
            # Fallback: look for a class-level description mapping
            elif hasattr(self.__class__, '__descriptions__'):
                desc = self.__class__.__descriptions__.get(name, '')
        result.append((name, desc))
    return result

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    attrs = set()
    mro = self.__class__.__mro__ if all else (self.__class__,)
    for cls in mro:
        ann = getattr(cls, '__annotations__', {})
        attrs.update(ann.keys())
        slots = getattr(cls, '__slots__', [])
        if isinstance(slots, str):
            slots = [slots]
        attrs.update(slots)
        for name, value in cls.__dict__.items():
            if name.startswith('_'):
                continue
            if callable(value):
                continue
            attrs.add(name)
    return sorted(attrs)

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    return not _c_optimizations_required()

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if self.initial_value is not None:
        self.bins = [self.initial_value] * len(self.bins)
    else:
        self.bins = self.make_bins()

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Retrieve points from the graph.  Support both list/tuple and dict.
    points = getattr(self, "points", None)
    if points is None:
        return "" if header is None else header

    if isinstance(points, dict):
        iterable = points.items()
    else:
        iterable = points

    lines = []
    for item in iterable:
        # Handle dict items (coord, value) or list/tuple of (coord, value)
        if isinstance(item, (list, tuple)):
            if len(item) != 2:
                continue
            coord, value = item
        else:
            # If the item is not a tuple/list, skip it
            continue

        # Convert coordinate to string parts
        if isinstance(coord, (str, bytes)):
            coord_parts = [coord]
        else:
            try:
                iter(coord)
            except TypeError:
                coord_parts = [str(coord)]
            else:
                coord_parts = [str(c) for c in coord]

        # Convert value to string parts
        if isinstance(value, (str, bytes)):
            value_parts = [value]
        else:
            try:
                iter(value)
            except TypeError:
                value_parts = [str(value)]
            else:
                value_parts = [str(v) for v in value]

        line = separator.join(coord_parts + value_parts)
        lines.append(line)

    if header is not None:
        if lines:
            return header + "\n" + "\n".join(lines)
        else:
            return header
    else:
        return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Ensure the mapping exists
    if not hasattr(self, "_err_indices"):
        raise AttributeError("Attribute '_err_indices' not found on the instance.")
    # Retrieve the indices for the given coordinate name
    indices = self._err_indices.get(coord_name)
    if indices is None:
        raise ValueError(f"No error indices found for coordinate '{coord_name}'.")
    # Normalise to a tuple of indices
    if isinstance(indices, (list, tuple)):
        return tuple(indices)
    return (indices,)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq is a Source instance, reject
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        pass

    # If seq itself is a FillRequest, accept
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        pass

    # Helper to determine if an object is a sequence (but not a string/bytes)
    def _is_sequence(obj):
        return isinstance(obj, (list, tuple, set, frozenset))

    # If seq is a sequence, check its elements
    if _is_sequence(seq):
        # Reject if all elements are Source instances
        try:
            if all(isinstance(x, Source) for x in seq):
                return False
        except NameError:
            pass
        # Accept if any element is a FillRequest
        try:
            return any(isinstance(x, FillRequest) for x in seq)
        except NameError:
            pass

    # For other iterable types (excluding str/bytes)
    try:
        it = iter(seq)
    except TypeError:
        return False
    if isinstance(seq, (str, bytes)):
        return False

    # Iterate and look for a FillRequest
    try:
        for item in it:
            if isinstance(item, FillRequest):
                return True
    except NameError:
        pass
    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return (
        hasattr(obj, 'fill') and callable(getattr(obj, 'fill'))
        and hasattr(obj, 'request') and callable(getattr(obj, 'request'))
    )

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return callable(getattr(obj, 'run', None))

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    if obj is None:
        return False
    return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))

def _validate_labels(labels):
    import re
    key_regex = re.compile(r'^[A-Za-z0-9]([-A-Za-z0-9_.]*[A-Za-z0-9])?$')
    value_regex = re.compile(r'^[A-Za-z0-9]([-A-Za-z0-9_.]*[A-Za-z0-9])?$')
    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue
        # Validate key format
        if not key_regex.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex [...]"})
        # Validate value
        if isinstance(value, list):
            for item in value:
                if not isinstance(item, (str, bytes)):
                    errors.append({str(item): 'expected string or bytes-like object'})
                else:
                    if not value_regex.match(item):
                        errors.append({item: f"Label value '{item}' does not match the regex [...]"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                if not value_regex.match(value):
                    errors.append({value: f"Label value '{value}' does not match the regex [...]"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer_schema dictionary from a Kubernetes
    resource manifest. Non-list and non-dict values are replaced with None.
    When first_level is True, identifying fields are copied from the manifest
    unchanged.
    """
    result = {}
    identifying_fields = {"apiVersion", "kind", "metadata"}
    for key, value in manifest_dict.items():
        if first_level and key in identifying_fields:
            # Copy identifying fields as-is
            result[key] = value
        else:
            if isinstance(value, dict):
                # Recurse into nested dictionaries
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
            elif isinstance(value, list):
                # Keep lists unchanged
                result[key] = value
            else:
                # Replace scalar values with None
                result[key] = None
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial ``last_applied_manifest`` list from a partial
    Kubernetes response.  The function walks through the ``observer_schema``
    describing the fields that should be present in the list items.  For each
    item in ``response`` it either updates an existing item in
    ``last_applied_manifest`` (matching by a key field if one is defined in
    the schema) or appends a new item.  Missing fields in the existing item
    are initialized from the response.  Nested dictionaries and lists are
    handled by delegating to the corresponding helper functions.
    """
    # Ensure we have a list to work with
    if last_applied_manifest is None:
        last_applied_manifest = []
    if response is None:
        return last_applied_manifest

    # Determine the key field used to match items in the list
    key_field = None
    for field in observer_schema:
        if field.get("key"):
            key_field = field.get("name")
            break

    # Build a lookup map for existing items
    if key_field:
        last_map = {
            item.get(key_field): item
            for item in last_applied_manifest
            if isinstance(item, dict)
        }
    else:
        last_map = {i: item for i, item in enumerate(last_applied_manifest)}

    # Process each item from the response
    for idx, resp_item in enumerate(response):
        if not isinstance(resp_item, dict):
            continue

        # Find the matching existing item
        if key_field:
            key = resp_item.get(key_field)
            last_item = last_map.get(key) if key is not None else None
        else:
            last_item = last_map.get(idx)

        # If no matching item, create a new one
        if last_item is None:
            new_item = {}
            for field in observer_schema:
                fname = field.get("name")
                if fname in resp_item:
                    new_item[fname] = resp_item[fname]
                else:
                    new_item[fname] = None
            last_applied_manifest.append(new_item)
            last_item = new_item
        else:
            # Update missing fields in the existing item
            for field in observer_schema:
                fname = field.get("name")
                # Skip if field already present and not None
                if fname in last_item and last_item[fname] is not None:
                    continue

                # If the field is present in the response, set it
                if fname in resp_item:
                    last_item[fname] = resp_item[fname]

                # Handle nested structures
                if "schema" in field:
                    sub_schema = field["schema"]
                    sub_resp = resp_item.get(fname)
                    if sub_resp is None:
                        continue
                    if isinstance(sub_schema, list):
                        # Nested list
                        if fname not in last_item or last_item[fname] is None:
                            last_item[fname] = []
                        update_last_applied_manifest_list_from_resp(
                            last_item[fname], sub_schema, sub_resp
                        )
                    else:
                        # Nested dict
                        if fname not in last_item or last_item[fname] is None:
                            last_item[fname] = {}
                        update_last_applied_manifest_dict_from_resp(
                            last_item[fname], sub_schema, sub_resp
                        )

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, schema_val in observer_schema.items():
        # Ensure the key exists in the response
        if key not in response:
            raise KeyError(f"Observed field '{key}' not found in response")
        # If the key is not yet in the last_applied_manifest, initialize it
        if key not in last_applied_manifest:
            if isinstance(schema_val, dict):
                # Nested dictionary: create an empty dict and recurse
                last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], schema_val, response[key]
                )
            elif isinstance(schema_val, list):
                # List: create an empty list and delegate to list handler
                last_applied_manifest[key] = []
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], schema_val, response[key]
                )
            else:
                # Scalar value: copy directly
                last_applied_manifest[key] = response[key]
        else:
            # Key already exists; if it's a nested structure, update it recursively
            if isinstance(schema_val, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], schema_val, response[key]
                )
            elif isinstance(schema_val, list):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], schema_val, response[key]
                )
            # For scalars, no action needed as the value is already present.

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application has a spec and a manifest
    spec = getattr(app, "spec", None)
    if spec is None:
        return
    manifest = getattr(spec, "manifest", None)
    if not manifest:
        return

    # Ensure the observer_schema dict exists
    observer_schema = getattr(spec, "observer_schema", None)
    if observer_schema is None:
        observer_schema = {}
        setattr(spec, "observer_schema", observer_schema)

    # Iterate over each resource in the manifest
    for resource in manifest:
        # Get the kind of the resource (dict or object)
        kind = None
        if isinstance(resource, dict):
            kind = resource.get("kind")
        else:
            kind = getattr(resource, "kind", None)

        if not kind:
            continue

        # Skip if a custom schema already exists for this kind
        if kind in observer_schema:
            continue

        # Generate a simple default schema for the resource kind
        default_schema = {
            "metadata": {
                "name": {"type": "string"},
                "namespace": {"type": "string"},
            },
            "spec": {"type": "object"},
            "status": {"type": "object"},
        }

        observer_schema[kind] = default_schema

    return observer_schema

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = getattr(self, 'status', None)
    if status is None:
        status_text = 'unknown'
    elif isinstance(status, bool):
        status_text = 'valid' if status else 'invalid'
    else:
        status_text = str(status)
    return f"{prefix}{status_text}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Try to find a log attribute
    log = getattr(self, 'log', None)
    if log is None:
        log = getattr(self, '_log', None)
    if log is None:
        log = getattr(self, '_validation_log', None)
    if log is None:
        return ''
    # If the log is a mapping, format key: value
    if isinstance(log, dict):
        return '\n'.join(f"{prefix}{k}: {v}" for k, v in log.items())
    # If the log is an iterable of strings (list, tuple, set, etc.)
    if isinstance(log, (list, tuple, set)):
        return '\n'.join(f"{prefix}{item}" for item in log)
    # Fallback: convert to string
    return f"{prefix}{log}"

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}

    # Case 1: inventory is a dict mapping version -> mapping of logical_path -> content_file(s)
    if isinstance(inventory, dict) and version in inventory:
        mapping = inventory[version]
        if isinstance(mapping, dict):
            for lp, cf in mapping.items():
                if cf is None:
                    continue
                # If the content file entry is a collection, add all items
                if isinstance(cf, (list, set, tuple)):
                    result.setdefault(lp, set()).update(cf)
                else:
                    result.setdefault(lp, set()).add(cf)
        else:
            # Unexpected structure; skip
            pass
    else:
        # Case 2: inventory is an iterable of entries (e.g., list of dicts)
        for entry in inventory:
            if not isinstance(entry, dict):
                continue
            if entry.get('version') != version:
                continue
            lp = entry.get('logical_path')
            cf = entry.get('content_file')
            if lp is None or cf is None:
                continue
            if isinstance(cf, (list, set, tuple)):
                result.setdefault(lp, set()).update(cf)
            else:
                result.setdefault(lp, set()).add(cf)

    return result

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        entries = os.listdir(path)
    except OSError:
        return []
    files = []
    for entry in entries:
        full_path = os.path.join(path, entry)
        if os.path.isfile(full_path):
            files.append(entry)
    return files

def select_filenames_by_prefix(prefix, files):
