def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _format(obj, level):
        space = ' ' * (level * 4)
        if isinstance(obj, (str, int, float, bool, type(None))):
            if debug:
                return f'{repr(obj)} ({type(obj).__name__})'
            return repr(obj)
        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                items.append(f'{_format(k, level+1)}: {_format(v, level+1)}')
            return '{\n' + ',\n'.join(space + '    ' + item for item in items) + '\n' + space + '}'
        if isinstance(obj, (list, tuple, set)):
            items = [_format(v, level+1) for v in obj]
            if isinstance(obj, list):
                open_br, close_br = '[', ']'
            elif isinstance(obj, tuple):
                open_br, close_br = '(', ')'
            else:
                open_br, close_br = '{', '}'
            return open_br + '\n' + ',\n'.join(space + '    ' + item for item in items) + '\n' + space + close_br
        # Custom object
        if hasattr(obj, '__dict__'):
            attrs = obj.__dict__
        else:
            attrs = {k: getattr(obj, k) for k in dir(obj) if not k.startswith('_') and not callable(getattr(obj, k))}
        items = []
        for k, v in attrs.items():
            items.append(f'{k}: {_format(v, level+1)}')
        return f'{obj.__class__.__name__}(' + '\n' + ',\n'.join(space + '    ' + item for item in items) + '\n' + space + ')'
    formatted = _format(self, 0)
    if indent:
        prefix = ' ' * indent
        return '\n'.join(prefix + line if line else '' for line in formatted.splitlines())
    return formatted

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Work on a mutable copy
    exprs = list(args)
    # Keep simplifying until no more changes
    changed = True
    while changed:
        changed = False
        # Use a copy of indices to avoid modifying list while iterating
        for i in range(len(exprs)):
            for j in range(len(exprs)):
                if i == j:
                    continue
                A = exprs[i]
                B = exprs[j]
                # Absorption: A & (A | B) = A
                try:
                    if B == A & (A | B):
                        exprs[j] = A
                        changed = True
                        continue
                except Exception:
                    pass
                # Absorption: A | (A & B) = A
                try:
                    if B == A | (A & B):
                        exprs[j] = A
                        changed = True
                        continue
                except Exception:
                    pass
                # Negative absorption: A & (~A | B) = A & B
                try:
                    if B == A & (~A | B):
                        exprs[j] = A & B
                        changed = True
                        continue
                except Exception:
                    pass
                # Negative absorption: A | (~A & B) = A | B
                try:
                    if B == A | (~A & B):
                        exprs[j] = A | B
                        changed = True
                        continue
                except Exception:
                    pass
    # Remove duplicates while preserving order
    seen = set()
    result = []
    for e in exprs:
        if e not in seen:
            seen.add(e)
            result.append(e)
    return result

def tzname_in_python2(namefunc):
    try:
        unicode
    except NameError:
        return namefunc
    def wrapper(*args, **kwargs):
        name = namefunc(*args, **kwargs)
        if name is None:
            return None
        if isinstance(name, unicode):
            return name.encode('utf-8')
        return name
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        from importlib.metadata import version, PackageNotFoundError
        # Try to determine the package name from the current module
        pkg_name = __package__ or __name__
        try:
            ver = version(pkg_name)
        except PackageNotFoundError:
            ver = "0.0.0"
        return {"version": ver}
    except Exception:
        return {"version": "0.0.0"}

def render(pieces, style):
    """
    Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : Iterable or Mapping
        The individual components of a version (e.g., major, minor, patch).
    style : str or callable
        The desired rendering style. Common string styles include:
        - "dot"      : join with '.'
        - "dash"     : join with '-'
        - "underscore": join with '_'
        - "raw"      : join with no separator
        - any format string containing placeholders (e.g., "{0}.{1}.{2}")
        If a callable is provided, it will be called with `pieces` and its
        return value will be used.

    Returns
    -------
    str
        The rendered version string.
    """
    # Handle None or empty pieces
    if not pieces:
        return ""

    # If pieces is a mapping (dict), try format with keyword arguments
    if isinstance(pieces, dict):
        if isinstance(style, str):
            try:
                return style.format(**pieces)
            except Exception:
                pass
        if callable(style):
            return style(pieces)
        # Fallback: return the dict as a string
        return str(pieces)

    # Ensure pieces is iterable
    try:
        iter(pieces)
    except TypeError:
        # Not iterable, treat as single component
        return str(pieces)

    # Handle string styles
    if isinstance(style, str):
        if style == "dot":
            return ".".join(map(str, pieces))
        if style == "dash":
            return "-".join(map(str, pieces))
        if style == "underscore":
            return "_".join(map(str, pieces))
        if style == "raw":
            return "".join(map(str, pieces))
        # Try format string with positional placeholders
        try:
            return style.format(*pieces)
        except Exception:
            pass

    # Handle callable styles
    if callable(style):
        return style(pieces)

    # Default: join with dots
    return ".".join(map(str, pieces))

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return '.' if '+' in pieces else '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, os, shlex

    # Build the command list
    if isinstance(commands, str):
        cmd = shlex.split(commands)
    else:
        cmd = list(commands)

    if isinstance(args, str):
        args = shlex.split(args)
    else:
        args = list(args)

    cmd.extend(args)

    if verbose:
        print("Running command:", " ".join(shlex.quote(c) for c in cmd))

    # Merge environment variables
    env_vars = os.environ.copy()
    if env:
        env_vars.update(env)

    # Decide where to send stderr
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_vars,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True,
            check=False,
        )
        return result.returncode
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command not found: {cmd[0]}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error running command {cmd[0]}: {exc}") from exc

def register_vcs_handler(vcs):
    """Create decorator to mark a method as the handler of a VCS."""
    def decorator(func):
        # Store the handler in a registry attached to the decorator function
        if not hasattr(register_vcs_handler, "registry"):
            register_vcs_handler.registry = {}
        register_vcs_handler.registry[vcs] = func
        return func
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    import os, hashlib
    num_objects = 0
    good_objects = 0
    root_path = getattr(self, 'root', None)
    if not root_path or not os.path.isdir(root_path):
        if show_warnings:
            print(f"Warning: root path '{root_path}' is not a valid directory.")
        return num_objects, good_objects
    for dirpath, dirnames, filenames in os.walk(root_path):
        for filename in filenames:
            file_path = os.path.join(dirpath, filename)
            num_objects += 1
            is_valid = True
            if validate_objects:
                try:
                    with open(file_path, 'rb') as f:
                        f.read(1)
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: cannot read file '{file_path}': {e}")
            if check_digests:
                digest_file = file_path + '.md5'
                if os.path.exists(digest_file):
                    try:
                        with open(digest_file, 'r') as df:
                            expected_digest = df.read().strip()
                        with open(file_path, 'rb') as f:
                            actual_digest = hashlib.md5(f.read()).hexdigest()
                        if actual_digest != expected_digest:
                            is_valid = False
                            if show_warnings:
                                print(f"Warning: digest mismatch for '{file_path}'. Expected {expected_digest}, got {actual_digest}.")
                    except Exception as e:
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: error checking digest for '{file_path}': {e}")
            if is_valid:
                good_objects += 1
    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    root = self.root_path
    if os.path.exists(root):
        if os.listdir(root):
