    else:
        os.makedirs(root)
    ocfl_root_file = os.path.join(root, ".ocfl_root")
    if os.path.exists(ocfl_root_file):
        raise FileExistsError(f".ocfl_root file already exists at {ocfl_root_file}.")
    ocfl_metadata = {
        "ocfl_version": "1.0",
        "layout": "v1",
        "layout_version": "1.0"
    }
    with open(ocfl_root_file, "w", encoding="utf-8") as f:
        f.write(json.dumps(ocfl_metadata, indent=2))
    objects_dir = os.path.join(root, "objects")
    os.makedirs(objects_dir, exist_ok=True)
    self.initialized = True

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return "1"
    parts = version.split('.')
    last = parts[-1]
    if last.isdigit():
        width = len(last)
        new_last = str(int(last) + 1).zfill(width)
        parts[-1] = new_last
    else:
        # If the last part is not purely numeric, append a suffix
        parts[-1] = f"{last}1"
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure attributes exist
    if not hasattr(self, 'root_inventory'):
        raise AttributeError("root_inventory attribute is required")
    if not hasattr(self, 'inventory_dir'):
        raise AttributeError("inventory_dir attribute is required")

    # Containers for differences and missing items
    self.different_digests = {}
    self.missing_items = {}

    missing_inventories = []

    for version_dir in version_dirs:
        inv_path = os.path.join(self.inventory_dir, version_dir, 'inventory.json')
        if not os.path.exists(inv_path):
            missing_inventories.append(version_dir)
            continue

        try:
            with open(inv_path, 'r', encoding='utf-8') as f:
                inv = json.load(f)
        except Exception as e:
            raise RuntimeError(f"Failed to load inventory '{inv_path}': {e}")

        # Compare digests with root inventory
        for content_id, digest in inv.items():
            root_digest = self.root_inventory.get(content_id)
            if root_digest is None:
                # Content not present in root; ignore or log
                continue
            if digest != root_digest:
                self.different_digests.setdefault(version_dir, {})[content_id] = (root_digest, digest)

        # Check for missing items relative to root inventory
        missing = set(self.root_inventory.keys()) - set(inv.keys())
        if missing:
            self.missing_items.setdefault(version_dir, set()).update(missing)

    if missing_inventories:
        raise FileNotFoundError(f"Missing inventory files for versions: {missing_inventories}")

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dict")
    if bug_ids:
        # Accept a single ID or an iterable of IDs
        if isinstance(bug_ids, (int, str)):
            bug_ids = [bug_ids]
        else:
            try:
                bug_ids = list(bug_ids)
            except TypeError:
                raise ValueError("bug_ids must be an iterable of bug IDs")
        # Convert all IDs to strings and join with commas
        params['ids'] = ','.join(str(bid) for bid in bug_ids)
    return params

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, value) tuples, deep merging MappingNode values for duplicate keys.
    """
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_values(v1, v2):
        # If both are MappingNode, deep merge their contents
        if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
            merged_pairs = deep_merge_nodes(v1.value + v2.value)
            return MappingNode(tag=v1.tag, value=merged_pairs)
        # Otherwise, the second value wins (last one)
        return v2

    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            existing_key_node, existing_value_node = merged[key]
            merged_value = merge_values(existing_value_node, value_node)
            merged[key] = (existing_key_node, merged_value)
        else:
            merged[key] = (key_node, value_node)

    return [(k, v) for k, v in merged.items()]

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    flags = []
    for action in parser._actions:
        flags.extend(action.option_strings)
    return ' '.join(flags)

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, value) tuples, deep merging MappingNode values
    for duplicate keys. Non-MappingNode values are overwritten by the last
    occurrence.
    """
    from collections import OrderedDict

    merged = OrderedDict()

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged:
            merged[key] = (key_node, value_node)
        else:
            _, existing_value = merged[key]
            # If both values are MappingNode, deep merge
            if (
                hasattr(existing_value, "tag")
                and existing_value.tag == "tag:yaml.org,2002:map"
                and hasattr(value_node, "tag")
                and value_node.tag == "tag:yaml.org,2002:map"
            ):
                # Merge the mapping node values recursively
                merged_list = deep_merge_nodes(
                    existing_value.value + value_node.value
                )
                merged[key] = (
                    key_node,
                    type(existing_value)(existing_value.tag, merged_list),
                )
            else:
                # Overwrite with the new value (last wins)
                merged[key] = (key_node, value_node)

    return list(merged.values())

