    return False

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Negative numbers are not supported")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two characters")
    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        # digits are least significant first, reverse them
        result = ''.join(reversed(digits))
    # Apply padding if requested
    if padding is not None:
        if padding < 0:
            raise ValueError("Padding must be non-negative")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result
    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    base = len(alphabet)
    if base == 1:
        raise ValueError("Alphabet must contain at least two symbols")
    # Build a mapping from character to its numeric value
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}
    value = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        value = value * base + char_to_value[ch]
    return value

def os_is_mac():
    """
    Checks if the os is macOS

