def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    # Remove surrounding single or double quotes
    if (name.startswith("'") and name.endswith("'")) or (name.startswith('"') and name.endswith('"')):
        return name[1:-1]
    # Remove any leading or trailing quotes
    return re.sub(r"(^['\"]|['\"]$)", "", name)

def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT,
            text=True
        )
    except subprocess.CalledProcessError:
        return ''
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    # Direct string checks for common localhost representations
    if host in ("localhost", "127.0.0.1", "::1"):
        return True
    try:
        # Resolve the host to all possible addresses
        for res in socket.getaddrinfo(host, None):
            ip = res[4][0]
            # IPv4 loopback check
            if ip.startswith("127."):
                return True
            # IPv6 loopback check
            if ip == "::1":
                return True
    except socket.gaierror:
        # Host could not be resolved
        return False
    return False

def make_find_paths(find_paths):
