@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Gather the base mapping of version -> handler class.
    # Prefer a class attribute named `_protocol_handlers`.  It may be
    # a dict or an iterable of handler classes that expose a
    # `protocol_version` attribute.
    base = getattr(cls, "_protocol_handlers", None)
    if base is None:
        # No explicit mapping; try to discover handler classes
        # defined as class attributes that have a `protocol_version`
        # attribute.
        base = {}
        for attr in vars(cls).values():
            if isinstance(attr, type) and hasattr(attr, "protocol_version"):
                base[attr.protocol_version] = attr
    elif isinstance(base, dict):
        # Already a mapping; nothing to do.
        pass
    else:
        # Assume an iterable of handler classes.
        base = {h.protocol_version: h for h in base}

    # If a specific protocol version is requested, validate and filter.
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        handler = base.get(protocol_version)
        return {protocol_version: handler} if handler else {}

    # No specific version requested; return a copy of all handlers.
    return dict(base)

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for
    subsequent use (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly
    recompute the scale if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Compute or recompute the integral if needed
    if recompute or getattr(self, "_scale", None) is None:
        # Try to compute the integral from bin contents and edges
        if hasattr(self, "_bins") and hasattr(self, "_edges"):
            try:
                integral = sum(
                    b * (e2 - e1)
                    for b, e1, e2 in zip(self._bins, self._edges[:-1], self._edges[1:])
                )
            except Exception:
                integral = 0.0
        else:
            integral = 0.0
        self._scale = integral

    # If no new scale requested, just return the current scale
    if other is None:
        return self._scale

    # Rescaling requested
    if not isinstance(other, (int, float)):
        raise TypeError("other must be a numeric value")
    if self._scale == 0:
        raise LenaValueError("Cannot rescale histogram with zero scale")

    factor = other / self._scale

    # Apply the scaling factor to the bin contents
    if hasattr(self, "_bins"):
        if isinstance(self._bins, (list, tuple)):
            self._bins = [b * factor for b in self._bins]
        else:
            # Assume array-like that supports in-place multiplication
            self._bins *= factor

    # Update the stored scale
    self._scale = other
    return None

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    del self[key]
    return value

def popitem(self):
    if self.size == 0:
        raise KeyError('popitem from an empty LRUCache')
    node = self.tail.prev
    node.prev.next = node.next
    node.next.prev = node.prev
    del self.cache[node.key]
    self.size -= 1
    return (node.key, node.value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self._data:
        raise KeyError('popitem from an empty LRUCache')
    key, value = self._data.popitem(last=True)
    return key, value

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    return re.compile(
        r'\bIN\s*(?:\(\s*(?P<params>:\w+(?:\s*,\s*:\w+)*)\s*\)|(?P<single>:\w+))',
        re.IGNORECASE
    )

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Handle both dict-like and object-like request structures
    if isinstance(request, dict):
        if request.get("public"):
            return True
        if request.get("private"):
            return True
        if request.get("legacy"):
            return True
    else:
        if getattr(request, "public", False):
            return True
        if getattr(request, "private", False):
            return True
        if getattr(request, "legacy", False):
            return True
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Matrix API endpoints start with /_matrix
    path = getattr(request, "path", None)
    if path is None:
        # Try to extract the path from a URL attribute if present
        url = getattr(request, "url", None)
        if url:
            try:
                from urllib.parse import urlparse
                path = urlparse(url).path
            except Exception:
                return False
    if not path:
        return False
    return path.startswith("/_matrix")

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The expected format is ISO 8601 with UTC timezone, e.g. '2023-04-05T12:34:56Z'.
    If the datetime is timezone-aware, it is converted to UTC before formatting.
    If the datetime is naive, it is assumed to be UTC.
    """
    # Convert to UTC if timezone-aware
    if dt.tzinfo is not None:
        offset = dt.utcoffset()
        if offset is not None:
            utc_dt = dt - offset
        else:
            utc_dt = dt
    else:
        utc_dt = dt
    # Format as ISO 8601 without microseconds, ending with 'Z'
    return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Empty tags are not allowed
    if not tag:
        return False
    # Optional length limit (e.g., 30 characters)
    if len(tag) > 30:
        return False
    # First character must be alphanumeric
    if not tag[0].isalnum():
        return False
    # Allowed characters: letters, digits, hyphen, underscore
    for ch in tag:
        if not (ch.isalnum() or ch in "-_"):
            return False
    return True

def xml_children_as_dict(node):
