    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    return {child.tag: child for child in node}

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    import base64
    from cryptography.hazmat.primitives import serialization, hashes
    from cryptography.hazmat.primitives.asymmetric import padding

    # Ensure inputs are bytes
    if isinstance(public_key, str):
        public_key_bytes = public_key.encode()
    else:
        public_key_bytes = public_key
    if isinstance(doc, str):
        doc_bytes = doc.encode()
    else:
        doc_bytes = doc
    if isinstance(signature, str):
        signature_bytes = base64.b64decode(signature)
    else:
        signature_bytes = signature

    # Load the public key
    try:
        pub_key = serialization.load_pem_public_key(public_key_bytes)
    except Exception as e:
        raise ValueError(f"Invalid public key: {e}")

    # Verify the signature
    try:
        pub_key.verify(
            signature_bytes,
            doc_bytes,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        return False

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        _, domain = handle.split('@', 1)
    except ValueError:
        return None
    resource = f'acct:{handle}'
    quote = __import__('urllib.parse').quote
    url = f'https://{domain}/.well-known/webfinger?resource={quote(resource)}'
    try:
        request = __import__('urllib.request')
        with request.urlopen(url, timeout=5) as resp:
            if resp.status == 200:
                return resp.read().decode('utf-8')
    except Exception:
        return None
    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Dynamically import required modules without top-level import statements
    urllib_request = __import__('urllib.request')
    urllib_parse = __import__('urllib.parse')
    urllib_error = __import__('urllib.error')
    json = __import__('json')

    if '@' not in handle:
        raise ValueError('Handle must be in the form user@domain')

    acct = f'acct:{handle}'
    domain = handle.split('@', 1)[1]
    query = urllib_parse.quote(acct, safe='')
    url = f'https://{domain}/.well-known/webfinger?resource={query}'

    req = urllib_request.Request(url, headers={'Accept': 'application/jrd+json'})

    try:
        with urllib_request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                raise RuntimeError(f'HTTP error {resp.status} while retrieving webfinger for {handle}')
            raw = resp.read().decode('utf-8')
            try:
                return json.loads(raw)
            except json.JSONDecodeError as e:
                raise RuntimeError(f'Failed to parse JSON from webfinger response for {handle}: {e}')
    except urllib_error.HTTPError as e:
        raise RuntimeError(f'HTTP error {e.code} while retrieving webfinger for {handle}: {e.reason}')
    except urllib_error.URLError as e:
        raise RuntimeError(f'URL error while retrieving webfinger for {handle}: {e.reason}')
    except Exception as e:
        raise RuntimeError(f'Unexpected error while retrieving webfinger for {handle}: {e}')

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    url = f"https://{host}/.well-known/host-meta"
    # Try to fetch the document using requests if available, otherwise fall back to urllib
    try:
        import requests
        resp = requests.get(url, timeout=5)
        resp.raise_for_status()
        data = resp.text
    except Exception:
        import urllib.request, urllib.error
        try:
            with urllib.request.urlopen(url, timeout=5) as f:
                data = f.read().decode('utf-8')
        except Exception as e:
            raise RuntimeError(f"Failed to retrieve host-meta from {host}") from e
    # Parse the XRD document
    try:
        from xrd import XRD
        return XRD.from_string(data)
    except Exception as e:
        raise RuntimeError(f"Failed to parse host-meta from {host}") from e

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        # Use the specified HTTP method; default to POST
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        return (None, exc)

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file names from the given directories that match the spec_option.

    Parameters
    ----------
    settings_dirs : Iterable[str]
        A collection of directory paths to search for files.
    spec_option : str or Iterable[str] or None
        If a string, it is treated as a glob pattern (e.g. '*.ini').
        If an iterable of strings, each string is treated as a file extension
        (e.g. ['.ini', '.cfg']).
        If None, all files are returned.

    Returns
    -------
    List[str]
        A sorted list of full file paths that match the specification.
    """
    import os
    import fnmatch

    matched_files = []

    # Normalise spec_option
    if spec_option is None:
        pattern = None
        extensions = None
    elif isinstance(spec_option, str):
        # Treat as glob pattern
        pattern = spec_option
        extensions = None
    else:
        # Treat as iterable of extensions
        pattern = None
        extensions = set()
        for ext in spec_option:
            if not ext.startswith('.'):
                ext = '.' + ext
            extensions.add(ext.lower())

    for dir_path in settings_dirs:
        if not os.path.isdir(dir_path):
            continue
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue
                if pattern:
                    if not fnmatch.fnmatch(entry, pattern):
                        continue
                elif extensions:
                    _, ext = os.path.splitext(entry)
                    if ext.lower() not in extensions:
                        continue
                matched_files.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return sorted(matched_files)

