def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names to allowed values.
    # If the attribute does not exist, nothing to validate.
    choices_map = getattr(self, "choices", {})
    if not isinstance(choices_map, dict):
        return

    for name, value in args.items():
        # Skip arguments that are not defined as choice arguments.
        if name not in choices_map:
            continue

        allowed = choices_map[name]
        # Skip validation for None values (e.g., optional arguments not provided).
        if value is None:
            continue

        # If the value is a sequence (list/tuple), validate each element.
        if isinstance(value, (list, tuple)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value '{v}' for argument '{name}'. "
                        f"Allowed values: {allowed}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value '{value}' for argument '{name}'. "
                    f"Allowed values: {allowed}"
                )

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Can be a dict of argument names to values,
                 or a list/tuple of values.
    """
    # Determine the iterable of (name, value) pairs
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        items = enumerate(args)
    else:
        raise TypeError("args must be a dict, list, or tuple")

    # Validate each value against self.min and self.max if they are defined
    for name, value in items:
        # Skip non-numeric values
        if not isinstance(value, (int, float)):
            continue

        if hasattr(self, "min") and self.min is not None and value < self.min:
            raise ValueError(
                f"Argument '{name}' value {value} is less than minimum {self.min}"
            )
        if hasattr(self, "max") and self.max is not None and value > self.max:
            raise ValueError(
                f"Argument '{name}' value {value} is greater than maximum {self.max}"
            )
    return True

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not extra_vars:
            return vars_dict
        for var in extra_vars:
            if not isinstance(var, str) or '=' not in var:
                continue
            key, val = var.split('=', 1)
            key = key.strip()
            val = val.strip()
            # Try to interpret JSON-like values
            if (val.startswith('{') and val.endswith('}')) or (val.startswith('[') and val.endswith(']')):
                try:
                    import json
                    parsed = json.loads(val)
                    vars_dict[key] = parsed
                    continue
                except Exception:
                    pass
            # Split comma-separated values into a list
            if ',' in val:
                vals = [v.strip() for v in val.split(',')]
                vars_dict[key] = vals
            else:
                vars_dict[key] = val
        return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Dynamically import required modules to avoid explicit import statements
    os = __import__('os')
    json = __import__('json')
    # Determine the spec file path (prefer JSON)
    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_path):
        # Fallback to YAML if JSON not found (simple parsing without external libs)
        spec_path = os.path.join(plugin_dir, 'plugin.yaml')
        if not os.path.exists(spec_path):
            return {}
        # Very naive YAML parser: only supports key: value pairs at top level
        def parse_yaml(path):
            data = {}
            with open(path, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    if ':' in line:
                        key, val = line.split(':', 1)
                        key = key.strip()
                        val = val.strip()
                        # Try to interpret as int or float
                        try:
                            val = int(val)
                        except ValueError:
                            try:
                                val = float(val)
                            except ValueError:
                                # Remove surrounding quotes if present
                                if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
                                    val = val[1:-1]
                        data[key] = val
            return data
        spec_dict = parse_yaml(spec_path)
    else:
        with open(spec_path, 'r', encoding='utf-8') as f:
            spec_dict = json.load(f)

    # Flatten nested dictionaries
    def flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return flatten(spec_dict)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        # Default to a config.yaml file in the current working directory
        default_path = os.path.join(os.getcwd(), 'config.yaml')
        os.environ['CONFIG_PATH'] = default_path
